 "content": "def transform(grid):
    """Color 4-cells lying strictly between 9s in any row or column with 2."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    mark = set()
    # Horizontal bounded runs
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 9:
                c += 1
                continue
            end = c + 1
            while end < w and grid[r][end] != 9:
                end += 1
            if end < w:
                for j in range(c + 1, end):
                    if grid[r][j] == 4:
                        mark.add((r, j))
            c = end
    # Vertical bounded runs
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 9:
                r += 1
                continue
            end = r + 1
            while end < h and grid[end][c] != 9:
                end += 1
            if end < h:
                for i in range(r + 1, end):
                    if grid[i][c] == 4:
                        mark.add((i, c))
            r = end
    for r, c in mark:
        out[r][c] = 2
    return out
